/* One catalogue drives staff configuration and the label purchase experience. */
const ui104={periods:{},settings:'plans',labelPackage:'all'};
function defaultFeatures104(name){const lang=ten.lang;try{ten.lang='id';const id=planFeatures103(name);ten.lang='en';const en=planFeatures103(name);return id.map((text,i)=>({id:text,en:en[i]}));}finally{ten.lang=lang;}}
const action104=(label,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-v104="${action}" data-id="${E(id)}">${label}</button>`;
function catalogue104(){
 ten.catalogue104??={version:1,creditPrice:35000,offers:{single:{quantity:1,bonus:0},ep:{quantity:4,bonus:1},album:{quantity:10,bonus:3}},plans:['Flex','Go','Pro','Business'].map((name,i)=>({id:name,name,group:name==='Business'?'multi':'single',monthly:null,annual:price103[name],discount:0,until:'',enabled:true,colors:[['#8a3b16','#db8c4e'],['#095b50','#29a38b'],['#0032bf','#5388ff'],['#48209b','#a276e5']][i],features:defaultFeatures104(name)})),history:[]};
 return ten.catalogue104;
}
function plan104(id){return catalogue104().plans.find(p=>p.id===id);}
function quote104(p,period){if(p.limited&&p.until&&ten.now>Date.parse(p.until+'T23:59:59+07:00'))return null;const base=p.id==='Flex'?catalogue104().creditPrice:period==='month'?p.monthly:p.annual;if(base===null||base===undefined)return null;const discount=p.discount&&(!p.until||ten.now<Date.parse(p.until+'T23:59:59+07:00'))?p.discount:0;return {base,total:Math.round(base*(1-discount/100)),discount};}
function coin104(){return '<span class="coin104" aria-hidden="true"><span>R</span></span>';}
function badge104(id){const p=plan104(id),colors=p?.colors||['#325877','#90a5b9'];return `<span class="plan9 plan103 package104" style="--package-dark:${colors[0]};--package-light:${colors[1]}">${E((p?.name||id).toUpperCase())}</span>`;}
function switch104(items,selected,action,label){return `<div class="switch104" role="group" aria-label="${E(label)}" style="--switch-count:${items.length};--switch-index:${Math.max(0,items.findIndex(x=>x[0]===selected))}"><i aria-hidden="true"></i>${items.map(([id,text])=>`<button type="button" data-v104="${action}" data-id="${E(id)}" class="${id===selected?'selected':''}" aria-pressed="${id===selected}">${text}</button>`).join('')}</div>`;}
function planCards104(){const c=catalogue104(),m=member10();return c.plans.filter(p=>p.enabled&&p.group===(ui103.group==='business'?'multi':'single')).map(p=>{const period=ui104.periods[p.id]||'year',q=quote104(p,period),current=m.plan===p.id;return `<article class="plan-card103 plan-card104 ${current?'current':''}" data-plan104="${E(p.id)}" style="--package-dark:${p.colors[0]};--package-light:${p.colors[1]}"><header>${badge104(p.id)}${current?`<span class="current-tag103">${T('Paketmu','Your plan')}</span>`:''}</header><h2>${E(p.name)}</h2>${p.id!=='Flex'?switch104([['month',T('Bulanan','Monthly')],['year',T('Tahunan','Annual')]],period,'plan-period',p.id):'<div class="flex-period104">'+T('Bayar sesuai jumlah lagu','Pay per track')+'</div>'}<div class="plan-price103">${q?`<small>Rp</small><strong>${new Intl.NumberFormat('id-ID').format(q.total)}</strong><span>/ ${p.id==='Flex'?T('kredit','credit'):period==='year'?T('tahun','year'):T('bulan','month')}</span>`:`<strong class="pending-price103">${p.limited&&p.until&&ten.now>Date.parse(p.until+'T23:59:59+07:00')?T('Penawaran berakhir','Offer ended'):T('Belum tersedia','Not available yet')}</strong>`}</div>${q?.discount?`<p class="offer-label104"><s>${money10(q.base)}</s> · ${T('Hemat','Save')} ${q.discount}%${p.until?' · '+T('hingga ','until ')+date10(p.until):''}</p>`:''}<ul class="benefits103">${p.features.map(x=>`<li><span aria-hidden="true">✓</span>${E(typeof x==='string'?x:T(x.id,x.en))}</li>`).join('')}</ul><div class="plan-bottom104">${current?`<p class="plan-until103">${expiry103(m)}</p>`:''}<button type="button" class="btn plan-cta103" data-v104="buy-plan" data-id="${E(p.id)}" ${q?'':'disabled'}>${p.id==='Flex'?T('Beli kredit','Buy credits'):current?T('Perpanjang paket','Renew plan'):'Switch to '+E(p.name)}</button></div></article>`;}).join('');}
plans10=function(){if(!isLabel10())return;const m=member10();fullscreen103(T('Pilihan paket','Choose your plan'),`<div class="plans103"><h1>${T('Ruang untuk setiap rilisan.','Room for every release.')}</h1><p class="current-plan103">${badge104(m.plan)}<span>${expiry103(m)}</span></p><div class="plan-switches103">${switch104([['single',T('1 label','Single label')],['business',T('Multi Label','Multi-label')]],ui103.group,'plan-group',T('Jenis paket','Plan type'))}${info10('prices104','Harga dan bonus dalam prototype adalah rancangan. Harga bulanan yang belum ditetapkan tidak ditawarkan untuk pembayaran.','Prototype pricing and bonuses are proposals. Monthly prices that are not configured cannot be purchased.')}</div><div class="plan-grid103">${planCards104()}</div></div>`,'plan-dialog103');};
function creditQuote104(quantity,preset){const offer=catalogue104().offers[preset];const bonus=offer&&quantity===offer.quantity?offer.bonus:0;return {quantity,bonus,total:quantity*catalogue104().creditPrice,received:quantity+bonus};}
purchase10=function(){if(!isLabel10())return;if(member10().invoice?.status==='pending')return invoice103();const b=RM10.balance(ten,member10()),c=catalogue104(),q=creditQuote104(ui103.quantity,ui103.preset);reviewDialogUI(T('Tambah kredit','Add credits'),`<div class="credit-checkout104"><header class="credit-heading104">${coin104()}<div><small>${T('Untuk rilisan berikutnya','For your next release')}</small><h2>${T('Tambahkan kreditmu.','Add to your credits.')}</h2></div></header><div class="credit-balance104"><span>${T('Tersedia','Available')} <strong>${b.daily+b.paid+b.replacement}</strong></span><span>${b.daily} ${T('harian','daily')} · ${b.paid} Flex · ${b.replacement} ${T('sementara','temporary')}</span></div><div class="credit-tiles103">${['single','ep','album','manual'].map(id=>{const o=c.offers[id];return `<button type="button" class="credit-tile103 ${ui103.preset===id?'selected':''}" data-v104="credit-preset" data-id="${id}" aria-pressed="${ui103.preset===id}"><span>${({single:'Single',ep:'EP',album:'Album',manual:T('Jumlah sendiri','Custom')})[id]}</span><strong>${o?o.quantity:T('Isi','Enter')}</strong><small>${o?T('kredit','credits'):T('jumlah kredit','credit amount')}</small>${o?.bonus?`<em>+${o.bonus} ${T('bonus','bonus')}</em>`:''}</button>`;}).join('')}</div><form data-v104-form="credits"><label class="credit-quantity103">${T('Jumlah kredit','Credit quantity')}<input name="quantity" id="credit-quantity104" type="number" min="1" max="500" step="1" required value="${ui103.quantity}"></label><div class="credit-note104"><span>✦</span><p>${T('Kredit Flex tetap tersedia tanpa batas waktu.','Flex credits remain available with no expiry.')}</p>${info10('credit-offer104','Contoh penawaran: EP mendapat 1 kredit tambahan dan Album 3. Nilainya dapat diatur Super Admin sebelum kebijakan final.','Sample offers: EP receives 1 extra credit and Album 3. Values can be configured before the final policy.')}</div>${paymentMethods103()}<section class="order103"><div><span>${T('Pembelian','Purchase')}</span><span id="credit-price104">${money10(q.total)}</span></div><div><span>${T('Kredit diterima','Credits received')}</span><strong id="credit-received104">${q.received}${q.bonus?' ('+q.quantity+' + '+q.bonus+' bonus)':''}</strong></div><div class="order-total103"><strong>${T('Total','Total')}</strong><strong id="credit-total104">${money10(q.total)}</strong></div></section><button class="btn primary purchase103" type="submit">${T('Lanjutkan pembayaran','Continue to payment')} ↗</button></form></div>`);$('#dialog').classList.add('credit-dialog104');};
creditPopup102=function(){purchase10();};
const baseInvoice104=invoice103;
invoice103=function(){const inv=member10().invoice;if(!inv?.quote104)return baseInvoice104();reviewDialogUI(T('Pembayaran','Payment'),`<div class="credit-checkout104"><header class="credit-heading104">${coin104()}<div><small>${E(inv.id)}</small><h2>${T('Selesaikan pembayaran','Complete your payment')}</h2></div></header><p>${T('Bayar sebelum','Pay before')} ${date10(inv.expires,true)} WIB</p><section class="order103"><div><span>${inv.kind==='credits'?inv.quote104.received+' '+T('kredit','credits'):E(inv.cataloguePlan104||inv.plan)+' · '+(inv.period==='month'?T('Bulanan','Monthly'):T('Tahunan','Annual'))}</span><strong>${money10(inv.quote104.total)}</strong></div><div><span>${T('Metode pembayaran','Payment method')}</span><span>${E(inv.method103)}</span></div></section>${action104(T('Bayar sekarang','Pay now'),'pay','','primary purchase103')}${info10('payment104','Pembayaran dalam prototype disimulasikan, tidak menarik uang. Harga pesanan dikunci saat dibuat.','Prototype payments are simulated and do not charge money. The price is locked when the order is created.')}</div>`);$('#dialog').classList.add('credit-dialog104');};
function cataloguePage104(){if(ten.role!=='super')return denied9();const c=catalogue104();return pageHead(T('Paket & Kredit','Plans & Credits'),'')+`<section class="panel pad catalogue104"><header class="section-heading104"><div><small>${T('PENAWARAN LAYANAN','SERVICE OFFERS')}</small><h2>${T('Pilihan untuk setiap label','Options for every label')}</h2></div>${ui104.settings==='plans'?action104(T('Tambah paket','Add plan'),'new-plan','','primary'):''}</header>${switch104([['plans',T('Paket layanan','Service plans')],['credits',T('Kredit rilisan','Release credits')]],ui104.settings,'catalogue-tab',T('Pengaturan penawaran','Offer settings'))}${ui104.settings==='plans'?`<div class="catalogue-list104">${c.plans.map(p=>`<article><div>${badge104(p.id)}<strong>${E(p.name)}</strong><small>${p.group==='multi'?T('Multi Label','Multi-label'):T('1 label','Single label')} · ${p.enabled?T('Ditawarkan','Available'):T('Disembunyikan','Hidden')}</small></div><div><span>${money10(p.id==='Flex'?c.creditPrice:p.annual)} / ${p.id==='Flex'?T('kredit','credit'):T('tahun','year')}</span><small>${p.id==='Flex'?T('Pembelian sesuai jumlah lagu','Purchase by track count'):p.monthly?money10(p.monthly)+' / '+T('bulan','month'):T('Bulanan belum ditetapkan','Monthly price not set')}</small></div>${action104(T('Ubah','Edit'),'edit-plan',p.id)}</article>`).join('')}</div>`:`<form data-v104-form="credit-config" class="ten-form"><label class="full">${T('Harga 1 kredit','Price per credit')}<input name="price" type="number" min="1" max="10000000" step="1" value="${c.creditPrice}" required></label>${['single','ep','album'].map(id=>`<fieldset class="offer-config104 full"><legend>${id==='ep'?'EP':id==='album'?'Album':'Single'}</legend>${field10(id+'Quantity',T('Jumlah pembelian','Purchase quantity'),c.offers[id].quantity,'number','min="1" max="500" required')}${field10(id+'Bonus',T('Kredit tambahan','Additional credits'),c.offers[id].bonus,'number','min="0" max="500" required')}</fieldset>`).join('')}<footer class="full review-footer-ui"><button type="submit" class="btn primary">${T('Simpan perubahan','Save changes')}</button></footer></form>`}${info10('catalogue104','Pengaturan prototype langsung dipakai pada pilihan paket dan pembelian kredit label. Pesanan yang sudah dibuat mempertahankan harga dan manfaat yang disepakati. Paket/kontrak aktif tidak diubah surut.','Prototype settings drive label plans and credit purchases. Existing orders retain their agreed prices and benefits. Active plans and contracts are not changed retroactively.')}<details><summary>${T('Riwayat perubahan','Change history')}</summary>${c.history.map(h=>`<p>${E(h.name)} · ${date10(h.at,true)} WIB</p>`).join('')||'<p>—</p>'}</details></section>`;}
function editPlan104(id){if(ten.role!=='super')return;const p=plan104(id)||{id:'',name:'',group:'single',annual:'',monthly:'',features:[],colors:['#244887','#6498eb'],discount:0,until:'',enabled:true};reviewDialogUI(T(id?'Ubah paket':'Paket baru',id?'Edit plan':'New plan'),`<form data-v104-form="plan" data-id="${E(id||'')}" class="ten-form">${field10('name',T('Nama paket','Plan name'),p.name,'text','required maxlength="32"')}${select10('group',T('Pengelolaan label','Label management'),[['single',T('1 label','Single label')],['multi',T('Multi Label','Multi-label')]],p.group)}${field10('annual',T('Harga tahunan','Annual price'),p.annual,'number','min="1" max="100000000" required')}${field10('monthly',T('Harga bulanan','Monthly price'),p.monthly??'','number','min="1" max="100000000"')}<label class="full">${T('Manfaat · satu per baris','Benefits · one per line')}<textarea name="features" rows="5" required>${E(p.features.map(f=>typeof f==='string'?f:T(f.id,f.en)).join('\n'))}</textarea></label>${field10('dark',T('Gradasi gelap','Dark gradient'),p.colors[0],'color','required')}${field10('light',T('Gradasi terang','Light gradient'),p.colors[1],'color','required')}<div class="full badge-preview104">${badge104(p.id||'Paket baru')}</div>${field10('discount',T('Potongan harga (%)','Discount (%)'),p.discount,'number','min="0" max="90" step="1" required')}${field10('until',T('Penawaran sampai','Offer until'),p.until,'date')}<label class="full ten-check"><input name="limited" type="checkbox" ${p.limited?'checked':''}>${T('Hentikan pembelian paket setelah tanggal penawaran','Stop plan purchases after the offer end date')}</label><label class="full ten-check"><input name="enabled" type="checkbox" ${p.enabled?'checked':''}>${T('Tampilkan pada pilihan paket','Show in plan selection')}</label><footer class="full review-footer-ui"><button class="btn primary" type="submit">${T('Simpan paket','Save plan')}</button></footer></form>`);}
const catalogueAct104=RM10.act;
RM10.act=function(s,action,p={}){
 if(action==='catalogue_save'){
  if(s.role!=='super')throw Error('permission');const c=catalogue104();
  if(p.kind==='credits'){if(!Number.isInteger(p.price)||p.price<1||p.price>10000000)throw Error('invalid');for(const o of Object.values(p.offers))if(!Number.isInteger(o.quantity)||o.quantity<1||o.quantity>500||!Number.isInteger(o.bonus)||o.bonus<0||o.bonus>500)throw Error('invalid');c.creditPrice=p.price;c.offers=structuredClone(p.offers);}
  else {const n=p.plan;if(!n.name.trim()||!['multi','single'].includes(n.group)||!Number.isInteger(n.annual)||n.annual<1||n.annual>100000000||(n.monthly!==null&&(!Number.isInteger(n.monthly)||n.monthly<1||n.monthly>100000000))||!n.features.length||!n.colors.every(x=>/^#[0-9a-f]{6}$/i.test(x))||!Number.isInteger(n.discount)||n.discount<0||n.discount>90||(n.until&&!Number.isFinite(Date.parse(n.until)))||(n.limited&&!n.until))throw Error('invalid');if(c.plans.some(x=>x.id!==n.id&&x.name.toLowerCase()===n.name.toLowerCase()))throw Error('duplicate');const previous=c.plans.find(x=>x.id===n.id);if(previous){Object.assign(previous,structuredClone(n));}else c.plans.push({...structuredClone(n),id:'plan-'+(++s.serial)});}
  c.version++;c.history.unshift({at:s.now,name:p.kind==='credits'?'Kredit rilisan':p.plan.name});return true;
 }
 if(action==='purchase104'){
  if(s.role!=='label')throw Error('permission');const m=RM10.getMember(s,s.member),c=catalogue104(),plan=plan104(p.plan);let quote;
  if(p.kind==='credits'){if(!Number.isInteger(p.quantity)||p.quantity<1||p.quantity>500)throw Error('invalid');quote=creditQuote104(p.quantity,p.preset);}else{if(!plan?.enabled)throw Error('invalid');quote=quote104(plan,p.period);if(!quote)throw Error('invalid');}
  const result=catalogueAct104(s,'invoice',{plan:p.kind==='credits'?'Flex':['Go','Pro','Business'].includes(plan.id)?plan.id:'Go',period:p.period,credits:p.quantity||1,kind:p.kind==='credits'&&m.paid?'credits':'activation'});
  Object.assign(m.invoice,{quote104:structuredClone(quote),cataloguePlan104:p.kind==='credits'?'Flex':plan.id,method103:p.method||'QRIS',benefits104:structuredClone(plan?.features||[]),catalogueVersion:c.version});return result;
 }
 if(action==='pay'){const m=RM10.getMember(s,p.member||s.member),inv=m.invoice,extra=inv?.quote104?.bonus||0;const result=catalogueAct104(s,action,p);if(inv?.quote104){if(inv.kind==='activation'){if(inv.cataloguePlan104!=='Flex')m.plan=inv.cataloguePlan104;m.benefits104=structuredClone(inv.benefits104);}if(extra&&!m.lots.some(l=>l.id==='offer-'+inv.id))m.lots.push({id:'offer-'+inv.id,type:'paid',available:extra,expires:null,source:'Penawaran kredit'});}return result;}
 return catalogueAct104(s,action,p);
};
window.addEventListener('click',e=>{const b=e.target.closest('[data-v104]');if(!b)return;const a=b.dataset.v104,id=b.dataset.id;if(!['plan-group','plan-period','buy-plan','credit-preset','pay','catalogue-tab','new-plan','edit-plan','catalogue-open'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();try{
 if(a==='plan-group'){ui103.group=id;plans10();}
 if(a==='plan-period'){const plan=b.closest('[data-plan104]').dataset.plan104;ui104.periods[plan]=id;const old=b.closest('[data-plan104]'),tmp=document.createElement('div');tmp.innerHTML=planCards104();old.replaceWith(tmp.querySelector('[data-plan104="'+plan+'"]'));enhanceSwitches104($('#dialog'));}
 if(a==='buy-plan'){if(id==='Flex')return purchase10();if(member10().invoice?.status==='pending')return invoice103();RM10.act(ten,'purchase104',{kind:'plan',plan:id,period:ui104.periods[id]||'year'});save10();invoice103();}
 if(a==='credit-preset'){ui103.preset=id;ui103.quantity=catalogue104().offers[id]?.quantity||ui103.quantity;purchase10();if(id==='manual')$('#credit-quantity104').focus();}
 if(a==='pay'){RM10.act(ten,'pay');save10();state.page='dashboard';render();reviewDialogUI(T('Pembayaran berhasil','Payment successful'),`<div class="reward-popup">${coin104()}<h2>${T('Pembayaran diterima.','Payment received.')}</h2><p>${member10().invoice.kind==='credits'?member10().invoice.quote104.received+' '+T('kredit tersedia untuk rilisanmu.','credits are ready for your releases.'):T('Paket pilihanmu sudah tersimpan.','Your selected plan has been saved.')}</p><button class="btn primary" data-global105="payment-done">${T('Buka Dashboard','Open Dashboard')}</button></div>`);}
 if(a==='catalogue-open'){if(ten.role!=='super')throw Error('permission');module102('catalogue104');render();}
 if(a==='catalogue-tab'){ui104.settings=id;render();}
 if(a==='edit-plan'&&id==='Flex'){ui104.settings='credits';render();return;}if(a==='new-plan'||a==='edit-plan')editPlan104(a==='new-plan'?'':id);
 }catch(err){toast(error10(err.message));}},true);
window.addEventListener('input',e=>{if(e.target.id==='credit-quantity104'){ui103.quantity=+e.target.value;ui103.preset='manual';const q=creditQuote104(ui103.quantity,'manual'),valid=Number.isInteger(q.quantity)&&q.quantity>0&&q.quantity<=500;$('#credit-price104').textContent=$('#credit-total104').textContent=valid?money10(q.total):'—';$('#credit-received104').textContent=valid?q.received:'—';document.querySelectorAll('.credit-tile103').forEach(b=>{b.classList.toggle('selected',b.dataset.id==='manual');b.setAttribute('aria-pressed',b.dataset.id==='manual');});}const f=e.target.closest('[data-v104-form=plan]');if(f){const el=f.querySelector('.package104');el.textContent=f.elements.name.value||T('Paket baru','New plan');el.style.setProperty('--package-dark',f.elements.dark.value);el.style.setProperty('--package-light',f.elements.light.value);}});
window.addEventListener('submit',e=>{const f=e.target,kind=f.dataset.v104Form;if(!kind)return;e.preventDefault();e.stopImmediatePropagation();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));try{
 if(kind==='credits'){RM10.act(ten,'purchase104',{kind:'credits',quantity:+v.quantity,preset:ui103.preset,method:v.method});save10();return invoice103();}
 if(kind==='credit-config')RM10.act(ten,'catalogue_save',{kind:'credits',price:+v.price,offers:Object.fromEntries(['single','ep','album'].map(id=>[id,{quantity:+v[id+'Quantity'],bonus:+v[id+'Bonus']}]))});
 if(kind==='plan')RM10.act(ten,'catalogue_save',{kind:'plan',plan:{id:f.dataset.id,name:v.name.trim(),group:v.group,annual:+v.annual,monthly:v.monthly?+v.monthly:null,features:v.features.split('\n').map(x=>x.trim()).filter(Boolean),colors:[v.dark,v.light],discount:+v.discount,until:v.until,limited:!!v.limited,enabled:!!v.enabled}});
 save10();closeModal();render();toast(T('Perubahan tersimpan.','Changes saved.'));
 }catch(err){toast(error10(err.message));}},true);
